class Queue:
    def __init__(self, maxsize):
        self.arr     = [None] * maxsize
        self.FRONT   = -1
        self.REAR    = -1
        self.MAXSIZE = maxsize

    def is_empty(self):
        return self.FRONT == -1

    def is_full(self):
        return self.REAR == self.MAXSIZE - 1

    def enqueue(self, x):
        if self.is_full():
            print("Queue Overflow")
            return
        if self.FRONT == -1 and self.REAR == -1:
            self.FRONT = 0
            self.REAR  = 0
        else:
            self.REAR += 1
        self.arr[self.REAR] = x

    def dequeue(self):
        if self.is_empty():
            print("Queue Underflow")
            return -1
        x = self.arr[self.FRONT]
        if self.FRONT == self.REAR:  # last element
            self.FRONT = -1
            self.REAR  = -1
        else:
            self.FRONT += 1
        return x

    def front(self):
        if self.is_empty():
            print("Queue is Empty")
            return -1
        return self.arr[self.FRONT]

    def rear(self):
        if self.is_empty():
            print("Queue is Empty")
            return -1
        return self.arr[self.REAR]


